<?php include 'config.php'; $msg=''; if(isset($_GET['delete'])) mysqli_query($conn,'DELETE FROM books WHERE book_id='.(int)$_GET['delete']);
if($_SERVER['REQUEST_METHOD']=='POST'){ $id=(int)$_POST['book_id']; $title=trim($_POST['title']); $author=trim($_POST['author']); $cat=trim($_POST['category']); if($id<=0||$title==''||$author==''||$cat==''){$msg='All fields required';} else {$stmt=mysqli_prepare($conn,'REPLACE INTO books VALUES(?,?,?,?)'); mysqli_stmt_bind_param($stmt,'isss',$id,$title,$author,$cat); mysqli_stmt_execute($stmt);}}
$s=mysqli_real_escape_string($conn,$_GET['search']??''); $res=mysqli_query($conn,"SELECT * FROM books WHERE title LIKE '%$s%' OR author LIKE '%$s%' ORDER BY book_id"); ?>
<!DOCTYPE html><html><head><title>Q14 Library</title><link rel="stylesheet" href="style.css"></head><body><div class="container"><h1>Library Book Tracking System</h1><form method="post"><input name="book_id" placeholder="Book ID"><input name="title" placeholder="Title"><input name="author" placeholder="Author"><input name="category" placeholder="Category"><button>Add/Update Book</button></form><p class="error"><?php echo $msg; ?></p><form method="get"><input name="search" placeholder="Search by title or author"><button>Search</button></form><table><tr><th>ID</th><th>Title</th><th>Author</th><th>Category</th><th>Action</th></tr><?php while($r=mysqli_fetch_assoc($res)){ ?><tr><td><?php echo $r['book_id']; ?></td><td><?php echo $r['title']; ?></td><td><?php echo $r['author']; ?></td><td><?php echo $r['category']; ?></td><td><a onclick="return confirmDelete()" href="?delete=<?php echo $r['book_id']; ?>">Delete</a></td></tr><?php } ?></table></div><script src="script.js"></script></body></html>
